---
102:[data-theme="boardroom"] .slide[data-layout="title"]::before,
103:[data-theme="boardroom"] .slide[data-layout="closing"]::before{content:"";position:absolute;inset-block:0;inset-inline-start:0;width:28px;background:var(--brand)}
106:[data-theme="boardroom"] .slide:not([data-tone="hero"]):not([data-layout="title"]):not([data-layout="section"]):not([data-layout="closing"]):not([data-layout="full-bleed"]) > h2{border-inline-start:8px solid var(--brand);padding-inline-start:28px}
122:[data-theme="swiss"] .slide:not([data-layout="title"]):not([data-layout="section"]):not([data-layout="closing"]):not([data-layout="full-bleed"]):not([data-tone="hero"])::before{content:"";position:absolute;top:0;inset-inline-start:120px;width:96px;height:20px;background:var(--brand)}
125:[data-theme="swiss"] [data-layout="bullets"]{display:grid;grid-template-columns:repeat(12,1fr);column-gap:40px;grid-template-rows:1fr;align-content:stretch}
126:[data-theme="swiss"] [data-layout="bullets"]>h2{grid-column:1/6;grid-row:1;align-self:start;margin:0;padding-top:48px}
127:[data-theme="swiss"] [data-layout="bullets"]>ul{grid-column:6/-1;grid-row:1;align-self:center;border-top:2px solid var(--ink);padding-top:40px;margin:0;padding-block-end:0}
128:[data-theme="swiss"] [data-layout="stats"] .stat b{border-top:0}
145:[data-theme="editorial"] .slide:not(:is([data-layout="title"],[data-layout="section"],[data-layout="closing"],[data-layout="full-bleed"],[data-tone="hero"]))::before{content:"";position:absolute;top:48px;inset-inline:120px;height:7px;border-top:2px solid var(--ink);border-bottom:1px solid var(--ink)}
237:.slide:is([data-layout="title"],[data-layout="section"],[data-layout="closing"],[data-layout="full-bleed"],[data-tone="hero"]):not([data-tone="plain"]){
259:[data-layout="title"]{justify-content:flex-end;padding-bottom:210px}
260:[data-layout="title"] .label{position:absolute;top:100px;inset-inline-start:120px;margin:0;white-space:nowrap}
261:[data-layout="title"] h1{max-width:1560px;margin-block-end:40px}
262:[data-layout="title"] .sub{font-size:calc(48px*var(--fit));line-height:1.25;color:var(--ink2);max-width:1240px}
267:[data-layout="section"]{justify-content:flex-end;padding-bottom:150px}
268:[data-layout="section"] .label{position:absolute;top:100px;inset-inline-start:120px;margin:0;white-space:nowrap}
269:[data-layout="section"] h2{font-size:calc(var(--t-display)*.95*var(--fit));max-width:1400px;margin-block-end:32px}
270:[data-layout="section"] p:not(.label):not(.src){font-size:calc(44px*var(--fit));color:var(--ink2);max-width:1000px}
274:[data-layout="statement"]{justify-content:center}
275:[data-layout="statement"] h2{font-size:calc(var(--t-h1)*var(--fit));line-height:1.02;max-width:1620px;margin:0}
276:[data-layout="statement"] p{margin-block-start:56px;font-size:calc(40px*var(--fit));color:var(--ink2);max-width:1000px}
277:[data-layout="statement"] .label{margin-block-end:48px}
279:[data-layout="agenda"]{display:grid;grid-template-columns:repeat(12,1fr);column-gap:40px;align-content:start}
280:[data-layout="agenda"] h2{grid-column:1/6;grid-row:1;align-self:start}
281:[data-layout="agenda"] .label{grid-column:1/6;grid-row:1;margin:0 0 20px}
282:[data-layout="agenda"]{grid-template-rows:1fr}
283:[data-layout="agenda"] ol{grid-column:6/13;grid-row:1;counter-reset:ag;list-style:none;padding:0;border-top:var(--rule-w,1px) solid var(--rule-strong);align-self:center}
284:[data-layout="agenda"] li{counter-increment:ag;display:grid;grid-template-columns:90px 1fr auto;align-items:baseline;gap:0 24px;padding:calc(34px*var(--fit)) 0;border-bottom:1px solid var(--rule);font-size:calc(56px*var(--fit));line-height:1.15;font-family:var(--f-display);font-weight:var(--w-display);letter-spacing:var(--ls-display)}
285:[data-layout="agenda"] li::before{content:counter(ag);font:500 var(--t-small) var(--f-mono);color:var(--brand-text);letter-spacing:0}
286:[data-layout="agenda"] li small{font:400 var(--t-small) var(--f-mono);color:var(--ink2);letter-spacing:0}
287:[data-layout="agenda"] ol:has([aria-current]) li:not([aria-current]){color:var(--ink2);font-weight:400}
289:[data-layout="bullets"] ul{display:flex;flex-direction:column;gap:calc(34px*var(--fit));max-width:1360px;list-style:none;padding:0;margin-block:auto;padding-block-end:40px}
290:[data-layout="bullets"] li{position:relative;padding-inline-start:60px;font-size:calc(var(--bs,52px)*var(--fit));line-height:1.22;text-wrap:balance}
291:[data-layout="bullets"] li::before{content:"";position:absolute;inset-inline-start:4px;top:.5em;width:20px;height:20px;background:var(--brand);border-radius:var(--radius,0);transform:translateY(-50%) scale(.8)}
292:[data-layout="bullets"] li small{display:block;font-size:.58em;line-height:1.35;margin-top:8px}
293:[data-layout="bullets"][data-n="3"]{--bs:60px}[data-layout="bullets"][data-n="4"]{--bs:54px}[data-layout="bullets"][data-n="5"]{--bs:48px}[data-layout="bullets"][data-n="6"]{--bs:42px}
295:[data-layout="two-column"] .cols{display:grid;grid-template-columns:repeat(12,1fr);column-gap:40px;margin-block:auto;padding-block-end:40px}
296:[data-layout="two-column"] .col{grid-column:span 6;padding-inline-end:56px;border-top:var(--rule-w,1px) solid var(--rule-strong);padding-top:32px}
297:[data-layout="two-column"] .col+.col{padding-inline-end:0}
298:[data-layout="two-column"] .col h3{margin-block-end:24px;font-size:calc(56px*var(--fit))}
299:[data-layout="two-column"] .col p{font-size:calc(40px*var(--fit));line-height:1.5;color:var(--ink2)}
300:[data-layout="two-column"] .col ul{list-style:none;padding:0;display:flex;flex-direction:column;gap:22px;font-size:calc(40px*var(--fit))}
301:[data-layout="two-column"] .col li{padding-inline-start:36px;position:relative;line-height:1.35}
302:[data-layout="two-column"] .col li::before{content:"";position:absolute;inset-inline-start:0;top:.62em;width:16px;height:2px;background:var(--brand)}
305:[data-layout="image-left"]{padding-inline-start:960px}
306:[data-layout="image-right"]{padding-inline-end:960px}
314:[data-layout="image-left"]>figure.fig{inset-inline-start:0}
315:[data-layout="image-right"]>figure.fig{inset-inline-end:0}
321:[data-layout="full-bleed"]{padding:0;justify-content:flex-end;color:var(--hero-ink)}
322:[data-layout="full-bleed"]:not(:has(.bleed)){background:var(--bleed-bg);--bg:var(--bleed-bg);--ink:var(--bleed-ink);--ink2:var(--bleed-ink);--brand-text:var(--bleed-ink);color:var(--bleed-ink)}
323:[data-layout="full-bleed"]:not(:has(.bleed))::before{content:"";position:absolute;inset:0;background:repeating-radial-gradient(circle at 100% 0,transparent 0 78px,color-mix(in srgb,var(--bleed-ink) 22%,transparent) 78px 80px)}
324:[data-layout="full-bleed"] .bleed{position:absolute;inset:0}
325:[data-layout="full-bleed"]:has(.bleed)::after{content:"";position:absolute;inset:0;background:var(--scrim)}
326:[data-layout="full-bleed"]:has(.bleed){--ink:var(--on-image);--ink2:var(--on-image);color:var(--on-image)}
327:[data-layout="full-bleed"]>:not(.bleed){position:relative;z-index:1;margin-inline:120px}
328:[data-layout="full-bleed"] h2{font-size:calc(var(--t-h1)*var(--fh));margin-block-end:120px;max-width:1400px}
329:[data-layout="full-bleed"] h2:has(+ p:not(.label)){margin-block-end:28px}
330:[data-layout="full-bleed"] h2 em{background:none;-webkit-text-fill-color:currentColor;color:inherit}
331:[data-layout="full-bleed"] p:not(.label):not(.src){font-size:44px;max-width:1100px;margin-block-end:110px}
332:[data-layout="full-bleed"] .label{color:inherit;position:absolute;top:96px;margin:0;margin-inline-start:120px}

