313:figure.fig{position:absolute;inset-block:0;width:840px;overflow:hidden;background:var(--bg2)}
314:[data-layout="image-left"]>figure.fig{inset-inline-start:0}
315:[data-layout="image-right"]>figure.fig{inset-inline-end:0}
316:figure.fig>img,.bleed{width:100%;height:100%;object-fit:cover;display:block}
318:figure.fig:not(:has(img))::before{content:"";position:absolute;inset:0;background:repeating-radial-gradient(circle at 100% 100%,transparent 0 58px,var(--rule) 58px 60px)}
319:figure.fig:not(:has(img))::after{content:"";position:absolute;inset-inline-end:0;bottom:0;width:380px;height:380px;background:var(--brand);border-start-start-radius:100%}
420:[data-layout="diagram"] figcaption{font:var(--t-small)/1.3 var(--f-mono);color:var(--ink2);margin-top:16px}
464:[data-layout="rows"] h2{margin-block-end:36px}
465:[data-layout="rows"] .rows{list-style:none;padding:0;display:flex;flex-direction:column;border-top:2px solid var(--rule-strong)}
466:[data-layout="rows"] .rows>li{display:grid;grid-template-columns:280px 1fr;column-gap:40px;padding:calc(24px*var(--fit)) 0;border-bottom:1px solid var(--rule)}
467:[data-layout="rows"] .rows>li::before{content:attr(data-k);grid-row:1/span 2;font:500 max(28px,calc(28px*var(--fit)))/1.5 var(--f-mono);color:var(--brand-text)}
468:[data-layout="rows"] .rows>li>*{grid-column:2}
469:[data-layout="rows"] .rows h3{font-size:calc(40px*var(--fit));margin-block-end:6px}
470:[data-layout="rows"] .rows p{font-size:max(28px,calc(32px*var(--fit)));line-height:1.38;color:var(--ink2)}
471:[data-layout="rows"] .rows>li[data-hot]{background:var(--bg2);box-shadow:-28px 0 0 var(--bg2),28px 0 0 var(--bg2);border-bottom-color:var(--brand)}
472:[data-layout="rows"] .rows>li[data-hot] p{color:var(--ink)}
473:/* quiz: a question and 2 to 4 options; data-build="reveal" on the list marks the right answer on click */
474:[data-layout="quiz"]{justify-content:center}
475:[data-layout="quiz"] h2{font-size:calc(var(--t-h2)*var(--fit));margin-block-end:64px;max-width:1560px}
476:[data-layout="quiz"] .opts{list-style:none;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:36px 40px;counter-reset:q}
477:[data-layout="quiz"] .opts li{counter-increment:q;display:flex;align-items:center;gap:28px;border:max(var(--rule-w,1px),2px) solid var(--rule-strong);border-radius:var(--radius);padding:calc(40px*var(--fit)) 40px;font-size:calc(50px*var(--fit));line-height:1.22;transition:background-color .4s,color .4s,border-color .4s}
478:[data-layout="quiz"] .opts li::before{content:counter(q,upper-alpha);flex:none;width:84px;height:84px;display:grid;place-items:center;border-radius:50%;background:var(--bg2);color:var(--ink);font:700 42px/1 var(--f-display)}
479:[data-layout="quiz"] .opts li[data-correct]{background:var(--brand);border-color:var(--brand);color:var(--on-brand)}
480:[data-layout="quiz"] .opts li[data-correct]::before{background:var(--on-brand);color:var(--brand-text)}
