import { writeFileSync } from 'node:fs';
const f1 = (n) => n.toFixed(1);

// 1. Dot grids: simple random (spread) vs convenience (clumped). Illustrative only.
const cols = 8, rows = 5, gap = 44;
function grid(x0, y0, picked) {
  let s = '';
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const x = x0 + c * gap, y = y0 + r * gap;
    const on = picked.some(([pc, pr]) => pc === c && pr === r);
    s += on ? `<circle class="dg-dot" cx="${x}" cy="${y}" r="13" style="fill:var(--brand)"/>`
            : `<circle class="dg-dot" cx="${x}" cy="${y}" r="8" style="fill:var(--rule)"/>`;
  }
  return s;
}
const random = [[0,1],[2,4],[3,0],[5,2],[7,4],[1,3],[6,0],[4,1]];
const clump = [[0,0],[1,0],[2,0],[0,1],[1,1],[2,1],[0,2],[1,2]];
const dots = `
      <g data-build="fade" data-order="1">${grid(120, 70, random)}</g>
      <g data-build="fade" data-order="2"><text class="dg-t" x="300" y="330" text-anchor="middle">Simple random: every person has the same chance</text></g>
      <g data-build="fade" data-order="3">${grid(1000, 70, clump)}</g>
      <g data-build="fade" data-order="4"><text class="dg-t" x="1180" y="330" text-anchor="middle">Convenience: whoever is easiest to reach</text></g>`;
writeFileSync('/tmp/kp-gen/dots.svg', dots);

// 2. Two curves: symmetric (mean = median) and right-skewed (mean > median).
function panel(pdf, a, b, x0, W, base, H, curveClass) {
  const N = 120, xs = [], ys = [];
  let peak = 0;
  for (let i = 0; i <= N; i++) { const x = a + (b - a) * i / N; const y = pdf(x); xs.push(x); ys.push(y); peak = Math.max(peak, y); }
  const px = (x) => x0 + (x - a) / (b - a) * W;
  const py = (y) => base - y / peak * H;
  let d = `M${f1(px(xs[0]))} ${f1(base)}`;
  xs.forEach((x, i) => { d += `L${f1(px(x))} ${f1(py(ys[i]))}`; });
  d += `L${f1(px(xs[N]))} ${f1(base)}`;
  // median: cumulative integral
  let cum = 0, total = ys.reduce((s, y) => s + y, 0), median = a, mean = 0;
  for (let i = 0; i <= N; i++) { mean += xs[i] * ys[i]; }
  mean /= ys.reduce((s, y) => s + y, 0);
  for (let i = 0; i <= N; i++) { cum += ys[i]; if (cum >= total / 2) { median = xs[i]; break; } }
  return { d, mean, median, px, base, curveClass, x0, W };
}
const norm = (x) => Math.exp(-x * x / 2);
const gamma = (x) => (x <= 0 ? 0 : x * Math.exp(-x));   // shape 2, scale 1: mean 2, median about 1.68
const A = panel(norm, -3.5, 3.5, 60, 640, 470, 300);
const B = panel(gamma, 0, 8, 900, 640, 470, 300);
